contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // adr: recipient for multiplicate; amount: value to send with the call
    function run(address adr, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);
        // Observe owner and balance before
        address ownerBefore = c.Owner(); if (__ESBMC_reverted()) return;
        uint beforeBal = address(c).balance;

        bool reverted;
        c.multiplicate{value: amount}(adr); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Observe owner and balance after
        address ownerAfter = c.Owner(); if (__ESBMC_reverted()) return;
        uint afterBal = address(c).balance;

        // General rule:
        // - The Owner public variable never changes due to multiplicate (ownerBefore == ownerAfter).
        // - If the call reverted then balance is unchanged.
        // - If the call succeeded then the contract balance cannot have increased (afterBal <= beforeBal + amount)
        //   and if it actually sent funds (afterBal < beforeBal + amount) that still implies Owner stayed the same.
        assert(
            ownerBefore == ownerAfter
            && (reverted ? afterBal == beforeBal : afterBal <= beforeBal + amount)
        );
    }

    receive() external payable {}
}

